// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 seed1, uint256 seed2) public {
        // Bound seeds to reasonable ranges
        uint256 balance = bound(seed1, 10 ether, 1000 ether);
        uint256 blockNumber = bound(seed2, 1, 1000);

        // Set up block number and contract balance
        vm.roll(blockNumber);
        vm.deal(address(c), balance);

        // Initial contract balance
        uint256 initialBalance = address(c).balance;
        uint256 initialSenderBalance = address(this).balance;

        // Perform the fallback call
        (bool success,) = address(c).call{value: 10 ether}("");
        vm.assume(success);

        // Determine expected balance change
        if (blockNumber % 15 == 0) {
            // Transfer all balance to msg.sender
            assertTrue(address(c).balance == 0);
            assertTrue(address(this).balance == initialSenderBalance + initialBalance);
        } else {
            // Balance unchanged (no transfer)
            assertTrue(address(c).balance == initialBalance + 10 ether);
        }
    }
}

